// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 timestamp1, uint256 timestamp2) public {
        // Ensure both timestamps are in a reasonable range and timestamp2 is not strictly greater
        vm.assume(timestamp1 >= 1 && timestamp1 <= 1000000);
        vm.assume(timestamp2 >= 1 && timestamp2 <= 1000000);
        vm.assume(timestamp2 <= timestamp1);

        // Prepare ether for the fallback
        vm.deal(address(this), 20 ether);

        // First call with timestamp1
        vm.warp(timestamp1);
        payable(address(c)).call{value: 10 ether}("");

        // Second call with timestamp2 (not strictly greater)
        vm.warp(timestamp2);
        (bool success, ) = payable(address(c)).call{value: 10 ether}("");

        // The rule: the second call should revert if timestamp2 <= timestamp1 (strictly increasing required)
        assertTrue(success == (timestamp2 > timestamp1));
    }
}

